/** UTC instant of local wall time `HH:MM` on local date `YYYY-MM-DD` in `timeZone`. */
export function localTimeToUtc(dateISO: string, hhmm: string, timeZone: string): number {
  const [y, m, d] = dateISO.split("-").map(Number);
  const [hh, mm] = hhmm.split(":").map(Number);
  const wallMs = Date.UTC(y, m - 1, d, hh, mm);
  // Offsets on either side of any transition within a day of the wall time.
  const before = tzOffsetMinutes(timeZone, wallMs - 24 * 3600_000);
  const after = tzOffsetMinutes(timeZone, wallMs + 24 * 3600_000);
  const candidates = [before, after]
    .map((off) => ({ off, utc: wallMs - off * 60000 }))
    .filter((c) => tzOffsetMinutes(timeZone, c.utc) === c.off)
    .map((c) => c.utc);
  // Ambiguous (clocks go back): earliest occurrence. Nonexistent (clocks go
  // forward): interpret with the pre-transition offset, i.e. shift forward.
  return candidates.length ? Math.min(...candidates) : wallMs - before * 60000;
}

